CHARSET_CAVEAT = ("SRFI-13 spells the criterion as a CHAR-SET. Motoi has no char-set type, so the criterion "
  "here is a single character (#\\a) or a one-argument predicate on characters "
  "((lambda (c) (char-alphabetic? c))). Passing a multi-character string raises an error rather than "
  "being read as a set of characters.")
COERCE_CAVEAT = ("Arguments are coerced to strings rather than type-checked, so a non-string does not raise. "
  "(string-null? (list)) is #t because the empty list coerces to the empty string. Check with string? first "
  "if the input is untrusted.")

